  who.online++; who.lastSeen = now();
  if (isPoker(t) && p) pkSchedule(t);               // someone connected: a waiting table can start
  if (p && p.banker) t.hostSeen = now();
  const client = { res, uid: user.id, role };
  t.clients.add(client);
  res.write(`event: state\ndata: ${JSON.stringify(snapshot(t, role, user.id))}\n\n`);
  broadcast(t);
