    const t = tables.get(String(raw).toUpperCase());
    if (!t) continue;
    if (!t.players.has(user.id) && !t.viewers.has(user.id)) { try { watch(t, user); } catch { continue; } }
    const role = t.players.has(user.id) ? 'player' : 'viewer';
    const rec = role === 'player' ? t.players.get(user.id) : t.viewers.get(user.id);
    rec.online++; rec.lastSeen = now();
    const wrap = { write(payload) { res.write(payload.replace(/^event: (\w+)\ndata: ([\s\S]*)\n\n$/, (m, ev, data) => `event: ${ev}\ndata: {"code":"${t.code}","d":${data}}\n\n`)); } };
