// ===================== housekeeping =====================
setInterval(() => {
  const ts = now();
  for (const t of [...tables.values()]) {
    for (const p of [...t.players.values()]) {
      if (p.banker || p.bot) continue;
      if (p.online === 0 && ts - p.lastSeen > OFFLINE_MS && !(t.phase === 'betting' && p.staked > 0 && t.deadline)) leave(t, { id: p.uid }, false);
    }
    for (const v of [...t.viewers.values()]) if (v.online === 0 && ts - v.lastSeen > 30000) { t.viewers.delete(v.uid); vsys(t, `${v.name} left the gallery.`); }
    if (t.banker) {
      const host = t.players.get(t.hostId);
      if (host && host.online > 0) t.hostSeen = ts;
      else if (ts - t.hostSeen > HOST_AWAY_MS) { closeTable(t, null, 'The banker has been away for a while — table closed and bank cashed out.'); continue; }
    }
    if (isParallel(t) && ts - (t.lastTick || t.created) > PARALLEL_TICK_MS) { t.lastTick = ts; t.round++; }
    if (t.practice && !seated(t).some(p => !p.bot) && !t.viewers.size) { clearTimer(t); clearTimeout(t.next); for (const q of seated(t)) if (seats.get(seatKey(q.uid, t.game)) === t.code) seats.delete(seatKey(q.uid, t.game)); tables.delete(t.code); continue; }
    if (seatCount(t) === 0 && t.viewers.size === 0 && !t.banker && !t.bot && t.emptySince && ts - t.emptySince > EMPTY_TTL) {
      clearTimer(t); clearTimeout(t.next); tables.delete(t.code);
    }
  }
  for (const [k, v] of assigned) if (ts - v.ts > 60000) assigned.delete(k);
  for (const t of tables.values()) { touchQueue(t); if (t.queue.length) drainTable(t); }
  for (const g of sharedGames()) drainGlobal(g.id);
  for (const g of sharedGames()) {
    const empties = publicTablesFor(g.id).filter(t => seatCount(t) === 0);
    for (const t of empties.slice(1)) { clearTimer(t); clearTimeout(t.next); tables.delete(t.code); }
  }
}, 10000).unref();

// After a restart no table exists: refund escrowed bets, then hand every bank back to its host.
function recoverEscrow() {
  const owed = {};
  const rows = db.prepare(`SELECT user_id, game, json FROM game_state WHERE json LIKE '%"pending":{%'`).all();
  for (const r of rows) {
    const mod = games[r.game];
    if (!mod) continue;
    try { const s = JSON.parse(r.json).s; if (s && s.pending && s.pending.bank) owed[s.pending.bank] = (owed[s.pending.bank] || 0) + s.pending.total + (s.pending.fee || 0); } catch {}
    try { engine.run(stmt.userById.get(r.user_id), r.game, mod, null, {}, { fn: refundPending }); } catch (e) { console.error('escrow recovery failed', r.game, e.message); }
  }
  const midRound = db.prepare(`SELECT user_id, game FROM game_state WHERE json LIKE '%"shared":true%'`).all();
  for (const r of midRound) {
    const mod = games[r.game];
    if (!mod || !mod.shared || !mod.shared.recover) continue;
    try { engine.run(stmt.userById.get(r.user_id), r.game, mod, null, {}, { fn: ctx => { mod.shared.recover(ctx); } }); } catch (e) { console.error('round recovery failed', r.game, e.message); }
  }
  let banks = 0;
  for (const b of stmt.bankAll.all()) {
    const back = Math.max(0, b.amount - (owed[b.code] || 0));   // stakes already returned to their players above
    tx(() => { stmt.addBalance.run(back, back, b.host_id); stmt.bankDel.run(b.code); });
    banks++;
  }
  return rows.length + midRound.length + banks;
}

